<script lang="ts">
  import { useGameLanguageTick } from '../lib/useGameLanguageTick.svelte.ts';
  import type { GameRuntime } from '../types/game.js';

  const { trackGameLanguage } = useGameLanguageTick();

  function getGame(): GameRuntime | null {
    return (globalThis as { game?: GameRuntime }).game ?? null;
  }

  function t(key: string, fallback: string): string {
    const g = getGame();
    if (!g?.t) return fallback;
    const got = g.t(key);
    return got && got !== key ? got : fallback;
  }

  let labels = $derived.by(() => {
    trackGameLanguage();
    return {
      title: t('modal.logTitle', "Journal d'aventure"),
      empty: t('modal.logEmpty', 'Le journal enregistre les événements importants...'),
      clear: t('modal.logClear', "Effacer l'historique"),
      closeTitle: t('modal.guideCloseTitle', 'Fermer'),
    };
  });
</script>

<div class="modal-content log-modal-content" data-action="stopPropagation" data-action-stop>
  <div class="modal-header-logs">
    <h2 id="logModalTitleLabel">{labels.title}</h2>
    <button type="button" class="close-btn" data-action="closeLogModal" title={labels.closeTitle}>&times;</button>
  </div>
  <div id="gameLog" class="log-console-scroll">
    <div class="log-entry" id="logModalEmptyLabel" style="color:#94a3b8; font-style:italic; text-align:center; padding-top:20px;">
      {labels.empty}
    </div>
  </div>
  <div class="modal-footer-logs">
    <button class="btn" data-action="clearLogs"
      style="background: #ef4444; color: white; border:none; padding: 8px 16px; border-radius:6px; cursor:pointer; font-size:12px; font-weight:600;">
      &#x1F5D1;&#xFE0F; <span id="logModalClearLabel">{labels.clear}</span></button>
  </div>
</div>
